// Партия 2 синхронизации справочник -> календарь: луковичные и клубнелуковичные.
// tyulpan, narciss, krokus, muskari, podsnezhnik, liliya, georgin, gladiolus,
// iris, pion — у всех блок «Календарь работ по культуре» содержал только
// посадку + уборку отцветшего (+ иногда деление), тогда как .md расписывает
// подкормки, поливы, обработки, формировку, зимовку помесячно.
//
// Базовый регион — средняя полоса; для юга / Урал-Сибири / Северо-Запада те же
// работы со сдвигом месяца по документированному в regions_notes правилу
// (юг: весна/лето -1 мес, осень +1; Урал-Сибирь: весна/лето +1, осень -1;
// Северо-Запад ~ как средняя полоса). Северо-Западу добавлены точечные строки
// про ежегодную выкопку тюльпанов и укрытие лилий от вымокания.
//
// Источники (веб-поиск, сентябрь 2026):
// - Тюльпаны/нарциссы, 3 подкормки (всходы -> 2-3 лист/цветонос -> бутоны/после
//   цветения, фосфор-калий), совмещать с поливом:
//   ogorod.ru/ru/outdoor/tulip/9377, floristics.info/ru/stati/sadovodstvo/1612-nartsissy-ukhod
// - Георгины: подготовка клубней февраль-март, проращивание с конца апреля,
//   высадка после возвратных заморозков, первая подкормка не раньше недели
//   после высадки, пасынкование/подвязка:
//   botanichka.ru/article/podgotovka-prorashhivanie-i-posadka-klubney-georgin,
//   antonovsad.ru/georginy-posadka-i-uhod-1186
// - Гладиолусы: протравливание клубнелуковиц от трипса весной и осенью,
//   проращивание, окучивание, подкормки июнь-июль, 2-3 обработки от трипса за
//   сезон, полив/рыхление/мульча каждые 7-10 дней:
//   7dach.ru/Raspopov_Gennadiy/vrediteli-i-bolezni-gladiolusov-...-32643.html,
//   aogarden.ru/articles/tsvety-i-rasteniya/podkormka-gladiolusov-letnee-pitanie
// - Пионы: 2-я подкормка в бутонизацию (коровяк + сульфат калия + суперфосфат +
//   зола), 2-3 профилактические обработки от ботритиса с интервалом 10-14 дней,
//   первая — пролив по проросткам:
//   antonovsad.ru/uhod-za-pionami-...-2045, supersadovnik.ru/text/bolezni-pionov-seraja-gnil-1006631
// - Ирисы: подкормка сера/фосфор/калий с малой долей азота, весенняя
//   профилактика мягкой гнили корневищ фунгицидом, вычистка гнили до здоровой
//   ткани: goldwins.ru/blog/irisy-v-sadu-ukhod-vesnoy
// - Лилейный жук — ручной сбор с появления ростков, при массовом инсектицид;
//   деление гнёзд лилий через 4-6 недель после цветения (конец августа -
//   сентябрь): floristics.info (лилии, уход) — согласовано с docs/plants-src/liliya.md

const path = require('path');
const XLSX = require('xlsx');

const XLSX_PATH = path.resolve(__dirname, '..', '..', 'garden-data.xlsx');
const wb = XLSX.readFile(XLSX_PATH);
const calRows = XLSX.utils.sheet_to_json(wb.Sheets['Calendar']);

const MONTH_IDS = ['yanvar','fevral','mart','aprel','may','iyun','iyul','avgust','sentyabr','oktyabr','noyabr','dekabr'];
const MONTH_NAMES = ['ЯНВАРЬ','ФЕВРАЛЬ','МАРТ','АПРЕЛЬ','МАЙ','ИЮНЬ','ИЮЛЬ','АВГУСТ','СЕНТЯБРЬ','ОКТЯБРЬ','НОЯБРЬ','ДЕКАБРЬ'];

// сдвиг месяца от базового (средняя полоса) по сезону работы
function shifted(baseIdx, region) {
  if (region === 'srednyaya-polosa' || region === 'severo-zapad') return baseIdx;
  const season = baseIdx <= 4 ? 'spring' : (baseIdx <= 7 ? 'summer' : 'autumn'); // мар-май / июн-авг / сен-ноя
  const map = {
    yug:         { spring: -1, summer: -1, autumn: +1 },
    'ural-sibir':{ spring: +1, summer: +1, autumn: -1 },
  };
  let i = baseIdx + map[region][season];
  return Math.max(0, Math.min(11, i));
}

const SRC = 'ogorod.ru/ru/outdoor/tulip/9377; floristics.info/ru/stati/sadovodstvo/1612-nartsissy-ukhod; botanichka.ru/article/podgotovka-prorashhivanie-i-posadka-klubney-georgin; 7dach.ru/Raspopov_Gennadiy/...-32643.html; antonovsad.ru/uhod-za-pionami-...-2045; goldwins.ru/blog/irisy-v-sadu-ukhod-vesnoy';

// базовые (средняя полоса) записи: [baseMonthIdx, workType, [plants], text, {regions?}]
// regions по умолчанию все 4; можно сузить
