const newEntries = [];
for (const [baseIdx, workType, plants, text] of BASE) {
  for (const region of ['srednyaya-polosa','yug','ural-sibir','severo-zapad']) {
    const mi = shifted(baseIdx, region);
    newEntries.push({
      region,
      month: MONTH_IDS[mi],
      monthName: MONTH_NAMES[mi],
      workType,
      category: 'dekor',
      plants: plants.join(','),
      growMethod: 'grunt',
      text,
      detail: '',
      source: SRC,
    });
  }
}

// точечные строки только для Северо-Запада (documented в regions_notes)
function nw(baseIdx, workType, plants, text) {
  return { region: 'severo-zapad', month: MONTH_IDS[baseIdx], monthName: MONTH_NAMES[baseIdx],
    workType, category: 'dekor', plants: plants.join(','), growMethod: 'grunt', text, detail: '', source: SRC };
}
newEntries.push(
  nw(5, 'razmnozhenie', ['tyulpan'],
    'На Северо-Западе тюльпаны выкапывают ежегодно и строго на дренированной гряде — на сырых почвах луковицы выпревают и гниют. Просушка обязательна, хранение в проветриваемом сухом месте.'),
  nw(8, 'ukrytie', ['gladiolus','georgin'],
    'В прохладное сырое лето гладиолусы и георгины на Северо-Западе часто не успевают вызреть — берут ранние сорта, гряду делают дренированной, при угрозе ранних заморозков клубни выкапывают в первую очередь.'),
);

wb.Sheets['Calendar'] = XLSX.utils.json_to_sheet([...calRows, ...newEntries]);
wb.Sheets['Calendar']['!cols'] = [
  { wch: 16 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 },
  { wch: 24 }, { wch: 14 }, { wch: 60 }, { wch: 50 }, { wch: 40 },
];
XLSX.writeFile(wb, XLSX_PATH);

const by = {};
for (const e of newEntries) by[e.region] = (by[e.region] || 0) + 1;
console.log(`Партия 2 (луковичные): добавлено ${newEntries.length} строк`, JSON.stringify(by));
console.log(`Итого Calendar: ${calRows.length + newEntries.length} строк`);
